{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Doxazosin, the closest analogue (Morgan 0.3021), shares the 6,7-dimethoxy-4-aminoquinazoline core and has approximately 65% oral bioavailability in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bunazosin, another dimethoxyquinazoline analogue, has an absolute oral bioavailability of 44.1% in volunteers, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Trimazosin, with the same quinazoline-diamine scaffold, shows oral bioavailability of 61 ± 28%, providing additional transferable evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Amsacrine, which contains a sulfonamide anilide feature also present in the query, has 32% oral bioavailability, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Delavirdine, a heteroaromatic drug with sulfonamide and piperazine-like features, has 85% oral bioavailability, supporting that such polar/large substituents do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tariquidar is a less similar large dimethoxytetrahydroisoquinoline with low oral bioavailability in humans, providing a contradictory example, but its lower structural transferability and lack of the quinazoline diamine core reduce its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 6,7-dimethoxy-4-aminoquinazoline derivative closely related to doxazosin, bunazosin, and trimazosin, all of which have human absolute oral bioavailability of 44-65%, well above the 20% threshold. Additional analogues with sulfonamide and heteroaromatic features also show F >20%. The only low-F analogue, tariquidar, is less similar and lacks the quinazoline diamine core. Therefore high oral bioavailability (F >= 20%) is better supported.",
  "evidence_gaps": [
    "No direct pharmacokinetic or bioavailability measurement is available for the query molecule.",
    "Morgan similarity scores to all evidence molecules are low (<0.31), limiting quantitative transferability.",
    "No experimental data on solubility, permeability, first-pass metabolism, or efflux liability for the query.",
    "The low-bioavailability tariquidar example shares some lipophilic/sulfonamide features but its relevance to the quinazoline core is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

